```javascript
const fs = require('fs');

const [p, a] = fs.readFileSync(0, 'utf8').trim().split(/\r?\n/);

const counts = new Array(26).fill(0);
for (const ch of p) counts[ch.charCodeAt(0) - 97]++;

let valid = true;
for (const ch of a) {
  if (ch === '*') continue;
  const index = ch.charCodeAt(0) - 97;
  if (counts[index] === 0) {
    valid = false;
    break;
  }
  counts[index]--;
}

console.log(valid ? 'S' : 'N');
